-- Permission vocabulary and system roles of the deal module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the deal permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('campaign:create'::text, 'campaign'::text, 'create'::text, 'Create campaign'::text),
            ('campaign:delete'::text, 'campaign'::text, 'delete'::text, 'Delete campaign'::text),
            ('campaign:purge'::text, 'campaign'::text, 'purge'::text, 'Purge campaign'::text),
            ('campaign:read'::text, 'campaign'::text, 'read'::text, 'Read campaign'::text),
            ('campaign:restore'::text, 'campaign'::text, 'restore'::text, 'Restore campaign'::text),
            ('campaign:update'::text, 'campaign'::text, 'update'::text, 'Update campaign'::text),
            ('opportunity:create'::text, 'opportunity'::text, 'create'::text, 'Create opportunity'::text),
            ('opportunity:delete'::text, 'opportunity'::text, 'delete'::text, 'Delete opportunity'::text),
            ('opportunity:purge'::text, 'opportunity'::text, 'purge'::text, 'Purge opportunity'::text),
            ('opportunity:read'::text, 'opportunity'::text, 'read'::text, 'Read opportunity'::text),
            ('opportunity:restore'::text, 'opportunity'::text, 'restore'::text, 'Restore opportunity'::text),
            ('opportunity:update'::text, 'opportunity'::text, 'update'::text, 'Update opportunity'::text),
            ('opportunity_item:create'::text, 'opportunity_item'::text, 'create'::text, 'Create opportunity item'::text),
            ('opportunity_item:delete'::text, 'opportunity_item'::text, 'delete'::text, 'Delete opportunity item'::text),
            ('opportunity_item:purge'::text, 'opportunity_item'::text, 'purge'::text, 'Purge opportunity item'::text),
            ('opportunity_item:read'::text, 'opportunity_item'::text, 'read'::text, 'Read opportunity item'::text),
            ('opportunity_item:restore'::text, 'opportunity_item'::text, 'restore'::text, 'Restore opportunity item'::text),
            ('opportunity_item:update'::text, 'opportunity_item'::text, 'update'::text, 'Update opportunity item'::text),
            ('stage:create'::text, 'stage'::text, 'create'::text, 'Create stage'::text),
            ('stage:delete'::text, 'stage'::text, 'delete'::text, 'Delete stage'::text),
            ('stage:purge'::text, 'stage'::text, 'purge'::text, 'Purge stage'::text),
            ('stage:read'::text, 'stage'::text, 'read'::text, 'Read stage'::text),
            ('stage:restore'::text, 'stage'::text, 'restore'::text, 'Restore stage'::text),
            ('stage:update'::text, 'stage'::text, 'update'::text, 'Update stage'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('campaign:create'::text, 'campaign'::text, 'create'::text, 'Create campaign'::text),
            ('campaign:delete'::text, 'campaign'::text, 'delete'::text, 'Delete campaign'::text),
            ('campaign:purge'::text, 'campaign'::text, 'purge'::text, 'Purge campaign'::text),
            ('campaign:read'::text, 'campaign'::text, 'read'::text, 'Read campaign'::text),
            ('campaign:restore'::text, 'campaign'::text, 'restore'::text, 'Restore campaign'::text),
            ('campaign:update'::text, 'campaign'::text, 'update'::text, 'Update campaign'::text),
            ('opportunity:create'::text, 'opportunity'::text, 'create'::text, 'Create opportunity'::text),
            ('opportunity:delete'::text, 'opportunity'::text, 'delete'::text, 'Delete opportunity'::text),
            ('opportunity:purge'::text, 'opportunity'::text, 'purge'::text, 'Purge opportunity'::text),
            ('opportunity:read'::text, 'opportunity'::text, 'read'::text, 'Read opportunity'::text),
            ('opportunity:restore'::text, 'opportunity'::text, 'restore'::text, 'Restore opportunity'::text),
            ('opportunity:update'::text, 'opportunity'::text, 'update'::text, 'Update opportunity'::text),
            ('opportunity_item:create'::text, 'opportunity_item'::text, 'create'::text, 'Create opportunity item'::text),
            ('opportunity_item:delete'::text, 'opportunity_item'::text, 'delete'::text, 'Delete opportunity item'::text),
            ('opportunity_item:purge'::text, 'opportunity_item'::text, 'purge'::text, 'Purge opportunity item'::text),
            ('opportunity_item:read'::text, 'opportunity_item'::text, 'read'::text, 'Read opportunity item'::text),
            ('opportunity_item:restore'::text, 'opportunity_item'::text, 'restore'::text, 'Restore opportunity item'::text),
            ('opportunity_item:update'::text, 'opportunity_item'::text, 'update'::text, 'Update opportunity item'::text),
            ('stage:create'::text, 'stage'::text, 'create'::text, 'Create stage'::text),
            ('stage:delete'::text, 'stage'::text, 'delete'::text, 'Delete stage'::text),
            ('stage:purge'::text, 'stage'::text, 'purge'::text, 'Purge stage'::text),
            ('stage:read'::text, 'stage'::text, 'read'::text, 'Read stage'::text),
            ('stage:restore'::text, 'stage'::text, 'restore'::text, 'Restore stage'::text),
            ('stage:update'::text, 'stage'::text, 'update'::text, 'Update stage'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
